p=Path('app/src/main/java/com/rgapro1/ocaso/MainActivity.java')
s=p.read_text(encoding='utf-8')
if 'private String displayClientName(JSONObject p)' not in s:
    marker='    private boolean match(JSONObject p,String q)'
    helper='''    private String displayClientName(JSONObject p){String n=p.optString("name","").trim(),a=p.optString("surname","").trim();String full=(n+" "+a).trim();if(!full.isEmpty()&&!looksLikeOcr(full))return full;String h=p.optString("holder","").trim();return(!h.isEmpty()&&!looksLikeOcr(h))?h:"Cliente sin nombre";}\n    private boolean looksLikeOcr(String x){String u=x.toUpperCase(Locale.ROOT);return u.contains("DOCUMENTO")||u.contains("NNAOONAL")||u.contains("NACIONAL ESP");}\n'''
    if marker not in s: raise SystemExit('match marker not found')
    s=s.replace(marker,helper+marker,1)
pat=r'    private void clients\(\)\{.*?\n    private boolean match'
rep='''    private void clients(){page("Clientes","Nombre y apellidos son el dato principal");EditText q=edit("Nombre, DNI, NIE, CIF, teléfono, email, póliza…");content.addView(q,new LinearLayout.LayoutParams(-1,dp(54)));LinearLayout list=col();content.addView(list);Runnable refresh=()->{list.removeAllViews();JSONArray a=data();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null||!match(p,q.getText().toString()))continue;String name=displayClientName(p);String id=p.optString("identityNumber",p.optString("holderDni","—"));int docs=p.optJSONArray("documentPhotos")==null?0:p.optJSONArray("documentPhotos").length();int products=p.optJSONArray("products")==null?0:p.optJSONArray("products").length();Button x=action("👤  "+name+"\\nDNI/NIE: "+id+"  ·  "+products+" productos  ·  "+docs+" documentos",false);x.setTextSize(15);x.setOnClickListener(v->detail(p));list.addView(x,new LinearLayout.LayoutParams(-1,dp(82)));}if(list.getChildCount()==0)list.addView(tv("No se encontraron clientes.",15,MUTED,false));};q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){refresh.run();}public void afterTextChanged(android.text.Editable e){}});refresh.run();}\n    private boolean match'''
s,n=re.subn(pat,rep,s,flags=re.S)
if n!=1: raise SystemExit('clients replacement failed')

if 'private void attachDniPhotoToClient(JSONArray a)' not in s:
    marker='    private void save(JSONArray a){'
    helper='''    private void attachDniPhotoToClient(JSONArray a){\n        try{if(!dniMode||scanFile==null||!scanFile.isFile()||a==null||a.length()==0)return;JSONObject client=a.optJSONObject(a.length()-1);if(client==null)return;File dir=new File(getFilesDir(),"client_docs");if(!dir.exists()&&!dir.mkdirs())return;String key=client.optString("identityNumber",client.optString("holderDni",""));String safe=key.replaceAll("[^A-Za-z0-9_-]","_");if(safe.isEmpty())safe="cliente";File out=new File(dir,"dni_"+safe+"_"+System.currentTimeMillis()+".jpg");try(InputStream in=new FileInputStream(scanFile);OutputStream os=new FileOutputStream(out)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)os.write(b,0,n);}JSONArray docs=client.optJSONArray("documentPhotos");if(docs==null){docs=new JSONArray();client.put("documentPhotos",docs);}JSONObject d=new JSONObject();d.put("path",out.getAbsolutePath());d.put("name","DNI - foto original");d.put("type","DNI");d.put("mime","image/jpeg");d.put("source","OCR_CAMERA");d.put("createdAt",System.currentTimeMillis());docs.put(d);client.put("dniPhotoPath",out.getAbsolutePath());client.put("dniPhotoName","DNI - foto original");}catch(Exception ignored){}}\n'''
    if marker not in s: raise SystemExit('save marker not found')
    s=s.replace(marker,helper+marker,1)
s=s.replace('    private void save(JSONArray a){prefs.edit().putString("policies",a.toString()).apply();}','    private void save(JSONArray a){attachDniPhotoToClient(a);prefs.edit().putString("policies",a.toString()).apply();}',1)
p.write_text(s,encoding='utf-8')

