    add='''    private void editClientFinal(){LinearLayout l=col();EditText n=edit("Nombre");n.setText(client.optString("name",""));EditText a=edit("Apellidos");a.setText(client.optString("surname",""));EditText id=edit("DNI / NIE");id.setText(client.optString("identityNumber",client.optString("holderDni","")));EditText ph=edit("Teléfono");ph.setText(client.optString("phone",""));EditText em=edit("Email");em.setText(client.optString("email",""));EditText ad=edit("Dirección");ad.setText(client.optString("address",""));l.addView(n);l.addView(a);l.addView(id);l.addView(ph);l.addView(em);l.addView(ad);new AlertDialog.Builder(this).setTitle("Editar datos del cliente").setView(l).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{client.put("name",n.getText().toString().trim());client.put("surname",a.getText().toString().trim());client.put("identityNumber",id.getText().toString().trim());client.put("holderDni",id.getText().toString().trim());client.put("holder",(n.getText().toString().trim()+" "+a.getText().toString().trim()).trim());client.put("phone",ph.getText().toString().trim());client.put("email",em.getText().toString().trim());client.put("address",ad.getText().toString().trim());persistFinal();show(client);}catch(Exception e){toast("No se pudo guardar: "+e.getMessage());}}).show();}\n    private void addDocumentFinal(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,441);}\n    private void addProductFinal(){LinearLayout l=col();EditText t=edit("Tipo");EditText n=edit("Número");EditText e=edit("Vencimiento");l.addView(t);l.addView(n);l.addView(e);new AlertDialog.Builder(this).setTitle("Añadir producto/póliza").setView(l).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{JSONArray a=client.optJSONArray("products");if(a==null){a=new JSONArray();client.put("products",a);}JSONObject x=new JSONObject();x.put("type",t.getText().toString().trim());x.put("number",n.getText().toString().trim());x.put("expiry",e.getText().toString().trim());a.put(x);persistFinal();show(client);}catch(Exception z){toast("No se pudo añadir");}}).show();}\n    private void persistFinal(){try{JSONArray a=new JSONArray(prefs.getString("policies","[]"));for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null)continue;String pid=p.optString("identityNumber",p.optString("holderDni",""));if((!originalIdentityFinal.isEmpty()&&originalIdentityFinal.equalsIgnoreCase(pid))||client.toString().equals(p.toString())){a.put(i,client);prefs.edit().putString("policies",a.toString()).apply();return;}}}catch(Exception e){toast("No se pudo guardar: "+e.getMessage());}}\n    private void handleAddedDocumentFinal(Uri u){try{File dir=new File(getFilesDir(),"client_docs");if(!dir.exists())dir.mkdirs();String mime=getContentResolver().getType(u);String ext=mime!=null&&mime.contains("pdf")?".pdf":mime!=null&&mime.contains("png")?".png":".jpg";File out=new File(dir,"documento_"+System.currentTimeMillis()+ext);try(InputStream in=getContentResolver().openInputStream(u);OutputStream os=new FileOutputStream(out)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)os.write(b,0,n);}JSONArray a=client.optJSONArray("documentPhotos");if(a==null){a=new JSONArray();client.put("documentPhotos",a);}JSONObject dd=new JSONObject();dd.put("path",out.getAbsolutePath());dd.put("name",out.getName());dd.put("mime",mime==null?"application/octet-stream":mime);dd.put("addedAt",System.currentTimeMillis());a.put(dd);persistFinal();show(client);}catch(Exception e){toast("No se pudo añadir el documento: "+e.getMessage());}}\n    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==441&&resultCode==RESULT_OK&&data!=null&&data.getData()!=null)handleAddedDocumentFinal(data.getData());}\n'''
